// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // Fuzz parameters: from is an address (actor), v is any uint, tosCount decides length
    function testFuzz_property(address from, uint256 v, uint256 tosCount) public {
        // keep tosCount in a small but wide range so arrays are non-empty and manageable
        tosCount = bound(tosCount, 1, 8); // ensure at least one recipient so function proceeds

        // deploy a recording callee that implements transferFrom(address,address,uint256)
        // and always returns successfully (so the reference should return true)
        Recorder rec = new Recorder();

        // build the _tos array filled with the recorder address repeated tosCount times
        address[] memory tos = new address[](tosCount);
        for (uint i = 0; i < tosCount; i++) tos[i] = address(rec);

        // call transfer and capture whether it returned (no revert) and the returned bool via try/catch
        bool ok;
        try c.transfer(from, address(rec), tos, v) returns (bool retval) {
            ok = retval; // the contract returned; record its returned boolean
        } catch {
            ok = false; // if it reverted, consider it as false for this observation
        }

        // The reference implementation always returns true when all external calls succeed.
        // Our Recorder always accepts the calls (and records them), so for the correct C,
        // ok must be true for every admissible input. The mutant changing final `return true` to
        // `return false` will produce ok == false for the same inputs, so this assertion
        // distinguishes them.
        assertTrue(ok);
    }
}

// A minimal recording callee that matches the selector transferFrom(address,address,uint256)
// The function records each call's arguments so it's a valid observing counterparty.
contract Recorder {
    struct Call { address from; address to; uint256 v; }
    Call[] public calls;

    // This function matches the selector bytes4(keccak256("transferFrom(address,address,uint256)"))
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        calls.push(Call({from: from, to: to, v: v}));
        return true; // always success so reference returns true
    }
}
